import{_ as o,a0 as p,w as d,s as r,ao as n,I as t,x as s,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Linux 中实时监控日志文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中实时监控日志文件 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中实时监控日志文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中实时监控日志文件 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server]","title":"如何在 Linux 中实时监控日志文件","tag":"202208","desc":""},"relativePath":"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server].md","filePath":"[post].md"}'),u={name:"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server].md"};function g(h,i,k,b,f,m){const a=p("Link");return d(),r("div",null,[i[21]||(i[21]=n('<h1 id="如何在-linux-中实时监控日志文件" tabindex="-1">如何在 Linux 中实时监控日志文件 <a class="header-anchor" href="#如何在-linux-中实时监控日志文件" aria-label="Permalink to “如何在 Linux 中实时监控日志文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/19/194609f1njqu096uhy919i.jpg" alt=""></p><blockquote><p>本教程介绍了如何实时监控 Linux 日志文件（桌面、服务器或应用）以进行诊断和故障排除。</p></blockquote><p>当你在 Linux 桌面、服务器或任何应用中遇到问题时，你首先会查看单独的日志文件。日志文件通常是文本流和来自应用的带有时间戳的消息。它可以帮助你缩小特定问题的范围，并使你能够找到问题的原因。它还可以帮助从网络获得帮助。</p><p>一般来说，所有的日志文件都位于 <code>/var/log</code>。此目录包含特定应用和服务的扩展名为 <code>.log</code> 的日志文件，它还包含了其他含有日志的独立目录。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/log-files-in-var-log-1024x312.jpeg" alt="log files in var-log"></p><p>所以，如果你想监控一堆日志文件或特定的一个，这里有一些方法可以做到。</p><h3 id="linux-实时监控日志文件" tabindex="-1">Linux 实时监控日志文件 <a class="header-anchor" href="#linux-实时监控日志文件" aria-label="Permalink to “Linux 实时监控日志文件”">​</a></h3><h4 id="使用-tail-命令" tabindex="-1">使用 tail 命令 <a class="header-anchor" href="#使用-tail-命令" aria-label="Permalink to “使用 tail 命令”">​</a></h4><p><code>tail</code> 命令是实时跟踪日志文件的最基本方式。特别是如果你在只有终端而没有 GUI 的服务器中。这很有帮助。</p><p>基本语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail /path/to/log/file</span></span></code></pre></div><p>用法：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/Monitoring-multiple-log-files-via-tail.jpeg" alt="Monitoring multiple log files via tail"></p><p>可以使用开关 <code>-f</code> 跟踪实时更新的日志文件。例如，如果要关注 syslog，可以使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -f /var/log/syslog</span></span></code></pre></div><p>你可以使用单个命令监控多个日志文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -f /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>如果要监视 HTTP 或 sftp 或任何服务器，可以在此命令中使用它们各自的日志文件。</p><p>请记住，上述命令需要管理员权限。</p><h4 id="使用-lnav-日志文件浏览器" tabindex="-1">使用 lnav（日志文件浏览器） <a class="header-anchor" href="#使用-lnav-日志文件浏览器" aria-label="Permalink to “使用 lnav（日志文件浏览器）”">​</a></h4><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/lnav-Running.jpeg" alt="lnav Running"></p><p><code>lnav</code> 是一个出色的程序，你可以用它来用彩色编码的信息以更有条理的方式监控日志文件。在 Linux 系统中，这个工具不是默认安装的。你可以用下面的命令来安装它：</p><p>Ubuntu：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lnav</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install lnav</span></span></code></pre></div>',27)),t("p",null,[i[1]||(i[1]=s("lnav 的好处在于，如果你不想安装它，你可以下载其预编译的可执行文件并在任何地方运行它，甚至可以从 U 盘上运行。无需设置，并加载了功能。使用 lnav，你可以通过 SQL 查询日志文件，以及其他很酷的功能，你可以在其",-1)),e(a,{href:"https://lnav.org/features"},{default:l(()=>[...i[0]||(i[0]=[s("官方网站",-1)])]),_:1}),i[2]||(i[2]=s("上学习。",-1))]),i[22]||(i[22]=n(`<p>安装后，你可以在具有管理员权限的终端上运行 <code>lnav</code>，它会默认显示 <code>/var/log</code> 中的所有日志并开始实时监控。</p><h4 id="关于-systemd-的-journalctl-的一个说明" tabindex="-1">关于 systemd 的 journalctl 的一个说明 <a class="header-anchor" href="#关于-systemd-的-journalctl-的一个说明" aria-label="Permalink to “关于 systemd 的 journalctl 的一个说明”">​</a></h4><p>当今所有现代 Linux 发行版都主要使用 systemd。 systemd 提供了运行 Linux 操作系统的基本框架和组件。 systemd 通过 <code>journalctl</code> 提供日志服务，这有助于管理来自所有 systemd 服务的日志。你还可以使用以下命令实时监控各个 systemd 服务和日志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -f</span></span></code></pre></div><p>以下是一些特定的 <code>journalctl</code> 命令，可用于多种情况。你可以将这些与上面的 <code>-f</code> 选项结合使用以开始实时监控。</p><p>对于紧急系统消息，请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -p 0</span></span></code></pre></div><p>显示带有解释的错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -xb -p 3</span></span></code></pre></div><p>使用时间控制过滤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --since &quot;2022-12-04 06:00:00&quot;</span></span>
<span class="line"><span>journalctl --since &quot;2022-12-03&quot; --until &quot;2022-12-05 03:00:00&quot;</span></span>
<span class="line"><span>journalctl --since yesterday</span></span>
<span class="line"><span>journalctl --since 09:00 --until &quot;1 hour ago&quot;</span></span></code></pre></div>`,11)),t("p",null,[i[4]||(i[4]=s("如果你想了解更多关于 journalctl 的详细信息，我已经在这写了份 ",-1)),e(a,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:l(()=>[...i[3]||(i[3]=[s("指南",-1)])]),_:1}),i[5]||(i[5]=s("。",-1))]),i[23]||(i[23]=t("h3",{id:"结束语",tabindex:"-1"},[s("结束语 "),t("a",{class:"header-anchor",href:"#结束语","aria-label":"Permalink to “结束语”"},"​")],-1)),i[24]||(i[24]=t("p",null,"我希望这些命令和技巧可以帮助你找到桌面或服务器中问题/错误的根本原因。有关更多详细信息，你可以随时参考手册页并使用各种选项。如果你对本文有任何意见或想法，请使用下面的评论栏告诉我。",-1)),i[25]||(i[25]=t("p",null,"干杯。",-1)),i[26]||(i[26]=t("hr",null,null,-1)),t("p",null,[i[7]||(i[7]=s("via: ",-1)),e(a,{href:"https://www.debugpoint.com/monitor-log-files-real-time/"},{default:l(()=>[...i[6]||(i[6]=[s("https://www.debugpoint.com/monitor-log-files-real-time/",-1)])]),_:1})]),t("p",null,[i[12]||(i[12]=s("作者：",-1)),e(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...i[8]||(i[8]=[s("Arindam",-1)])]),_:1}),i[13]||(i[13]=s(" 选题：",-1)),e(a,{href:"https://github.com/lkxed"},{default:l(()=>[...i[9]||(i[9]=[s("lkxed",-1)])]),_:1}),i[14]||(i[14]=s(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:l(()=>[...i[10]||(i[10]=[s("geekpi",-1)])]),_:1}),i[15]||(i[15]=s(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[11]||(i[11]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[16]||(i[16]=[s("LCTT",-1)])]),_:1}),i[19]||(i[19]=s(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...i[17]||(i[17]=[s("Linux中国",-1)])]),_:1}),i[20]||(i[20]=s(" 荣誉推出",-1))])])}const y=o(u,[["render",g]]);export{v as __pageData,y as default};
